//! Pins the v2 wire encoding to canonical protoJSON (generated by pbjson): lowerCamelCase
//! field names, 64-bit integers as decimal strings, bytes as base64, oneofs flattened into
//! the parent object, and default values omitted. Deserialization accepts both camelCase
//! and the original proto field names.
//!
//! Changing any expectation here is a breaking change for every v2 REST client.

use espresso_api::proto;
use serde_json::json;

#[test]
fn u64_serializes_as_string() {
    let response = proto::BlockHeightResponse { height: u64::MAX };
    assert_eq!(
        serde_json::to_value(response).unwrap(),
        json!({"height": "18446744073709551615"})
    );
}

#[test]
fn bytes_serialize_as_base64() {
    let response = proto::RewardMerkleTreeV2Data {
        data: vec![1, 2, 3],
    };
    assert_eq!(
        serde_json::to_value(response).unwrap(),
        json!({"data": "AQID"})
    );
}

#[test]
fn oneof_flattens_into_parent_object() {
    let response = proto::GetNamespaceProofResponse {
        response: Some(proto::get_namespace_proof_response::Response::Range(
            proto::NamespaceProofRangeResponse { proofs: vec![] },
        )),
    };
    assert_eq!(
        serde_json::to_value(response).unwrap(),
        json!({"range": {}})
    );
}

#[test]
fn field_names_are_camel_case_and_defaults_are_omitted() {
    let response = proto::NodeKeysResponse {
        eth_account: None,
        consensus_key: Some(proto::BlsPublicKey {
            key: "BLS_VER_KEY~abc".to_string(),
        }),
        state_ver_key: None,
        x25519_key: None,
    };
    assert_eq!(
        serde_json::to_value(response).unwrap(),
        json!({"consensusKey": {"key": "BLS_VER_KEY~abc"}})
    );
}

#[test]
fn deserialize_accepts_both_field_name_forms_and_quoted_numbers() {
    let snake: proto::GetIncorrectEncodingProofRequest =
        serde_json::from_value(json!({"namespace_id": "7", "block_height": 9})).unwrap();
    let camel: proto::GetIncorrectEncodingProofRequest =
        serde_json::from_value(json!({"namespaceId": 7, "blockHeight": "9"})).unwrap();
    assert_eq!(snake, camel);
    assert_eq!(snake.namespace_id, 7);
    assert_eq!(snake.block_height, 9);
}

// The generated REST handlers extract requests with `axum::extract::Query`, which drives
// these same impls through serde_urlencoded rather than serde_json.
#[test]
fn query_params_decode_through_pbjson() {
    let request: proto::GetNamespaceProofRequest =
        serde_urlencoded::from_str("namespace_id=7&first=1&last=2").unwrap();
    assert_eq!(
        request,
        proto::GetNamespaceProofRequest {
            namespace_id: 7,
            block: None,
            first: Some(1),
            last: Some(2),
        }
    );
}

#[test]
fn empty_query_string_decodes_parameterless_and_defaulted_requests() {
    serde_urlencoded::from_str::<proto::GetBlockHeightRequest>("").unwrap();
    // Proto3 semantics: absent scalar fields take their default rather than erroring.
    let request: proto::GetStakeTableRequest = serde_urlencoded::from_str("").unwrap();
    assert_eq!(request.epoch, 0);
}
